-- Seed products from lib/products.ts (Phase 5)
on conflict (id) do update set
  sku = excluded.sku,
  name = excluded.name,
  category = excluded.category,
  tag = excluded.tag,
  price_inr = excluded.price_inr,
  image = excluded.image,
  image_verified = excluded.image_verified,
  specs_verified = excluded.specs_verified,
  active = true,
  updated_at = now();
